class Solution:
    def numOfBurgers(self, tomatoSlices: int, cheeseSlices: int) -> List[int]:
        for j in range(cheeseSlices + 1):
            rem = tomatoSlices - 4 * j
            if rem >= 0 and rem % 2 == 0 and j + rem // 2 == cheeseSlices:
                return [j, rem // 2]
        return []

