class Solution {
public:
    vector<int> numOfBurgers(int tomatoSlices, int cheeseSlices) {
        for (long long j = 0; j <= cheeseSlices; ++j) {
            long long rem = tomatoSlices - 4 * j;
            if (rem >= 0 && rem % 2 == 0 && j + rem / 2 == cheeseSlices)
                return {(int)j, (int)(rem / 2)};
        }
        return {};
    }
};

